#!/usr/bin/env python3
"""Phase B: active 实现补 column_id（test 平台 API，无需 MySQL）。

做法：
1) 拉 published 口径详情，收集 active 且缺/错 column_id 的实现
2) 用牺牲实现扫描 meta_entity 列 id（1..max），建 库.表.列 → id
3) PATCH 回填；最后把牺牲实现也修回正确列

用法：
  python3 docs/metric_library/metric_v2_backfill_column_id_20261127.py
  python3 ... --apply
  python3 ... --apply --max-id 16377 --workers 8
"""
from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path

BASE = os.environ.get("METADATA_API_BASE", "https://zsq18012.dcpusff.my").rstrip("/")
TOKEN_ENV = Path.home() / ".dc-platform/config/test-platform.env"
STATE = Path("/tmp/metric_v2_column_id_backfill_state.json")
SACRIFICE_IMPL = 371  # M000001 主实现；扫完会按映射修回


def load_token() -> str:
    if os.environ.get("DC_USER_TOKEN"):
        return os.environ["DC_USER_TOKEN"].strip()
    for line in TOKEN_ENV.read_text().splitlines():
        if line.startswith("DC_USER_TOKEN="):
            return line.split("=", 1)[1].strip()
    sys.exit("DC_USER_TOKEN missing")


TOKEN = load_token()


def req(method: str, path: str, data=None, retries: int = 5, timeout: int = 90):
    out = Path(f"/tmp/ml_bf_{os.getpid()}.json")
    last = ("000", "")
    for i in range(retries):
        cmd = [
            "/usr/bin/curl", "-sS", "--max-time", str(timeout),
            "-o", str(out), "-w", "%{http_code}",
            "-X", method,
            "-H", f"Authorization: Bearer {TOKEN}",
            "-H", "User-Agent: Mozilla/5.0",
            "-H", "Accept: application/json",
        ]
        body = None
        if data is not None:
            body = json.dumps(data, ensure_ascii=False)
            cmd += ["-H", "Content-Type: application/json", "--data-binary", body]
        cmd.append(BASE + path)
        p = subprocess.run(cmd, capture_output=True, text=True)
        code = (p.stdout or "").strip() or f"err{p.returncode}"
        text = out.read_text() if out.exists() else ""
        last = (code, text)
        if code in ("200", "201", "400", "404"):
            return code, text
        time.sleep(1.2 * (i + 1))
    return last


def list_published_codes() -> list[str]:
    """按 entity 分批 + M 号扫尾，绕过 list limit=500。"""
    codes: set[str] = set()
    # entity 列表来自已有 dimensions/entities
    c, b = req("GET", "/api/v1/metric-library/entities?limit=200")
    entities = []
    if c == "200" and b.startswith("{"):
        entities = [e.get("entity_code") for e in (json.loads(b).get("items") or []) if e.get("entity_code")]
    if not entities:
        entities = ["ad", "user", "order", "video", "app", "device", "channel"]
    for ent in entities:
        c, b = req("GET", f"/api/v1/metric-library/concepts?lifecycle_status=published&entity_code={ent}&limit=500")
        if c != "200":
            print(f"WARN concepts entity={ent} {c}")
            continue
        for it in json.loads(b).get("items") or []:
            codes.add(it["concept_code"])
        print(f"  entity {ent}: +{len(json.loads(b).get('items') or [])} total={len(codes)}")
    # 兜底扫 M 号
    miss = 0
    for n in range(1, 1201):
        code = f"M{n:06d}"
        if code in codes:
            continue
        c, b = req("GET", f"/api/v1/metric-library/concepts/{code}")
        if c == "200" and b.startswith("{"):
            d = json.loads(b)
            if d.get("lifecycle_status") == "published":
                codes.add(code)
            miss = 0
        else:
            miss += 1
            if miss >= 40:
                break
    return sorted(codes)


def collect_targets(codes: list[str]) -> list[dict]:
    targets = []
    for i, code in enumerate(codes, 1):
        c, b = req("GET", f"/api/v1/metric-library/concepts/{code}/detail")
        if c != "200" or not b.startswith("{"):
            print(f"WARN detail {code} {c}")
            continue
        d = json.loads(b)
        for impl in d.get("implementations") or []:
            if impl.get("impl_status") != "active":
                continue
            t = (impl.get("table_fqn") or "").strip()
            col = (impl.get("column_name") or "").strip()
            if not t or not col:
                continue
            fqn = f"{t}.{col}"
            cur = impl.get("column_id")
            # 已正确锚上则跳过（column.fqn 对齐）
            col_meta = impl.get("column") or {}
            if cur and col_meta.get("fqn") == fqn:
                continue
            targets.append({
                "impl_id": impl["id"],
                "concept_code": code,
                "table_fqn": t,
                "column_name": col,
                "fqn": fqn,
                "column_id": cur,
                "is_primary": bool(impl.get("is_primary")),
            })
        if i % 50 == 0:
            print(f"  detail {i}/{len(codes)} targets={len(targets)}")
    return targets


def probe_id(mid: int) -> tuple[int, str | None]:
    c, b = req(
        "PATCH",
        f"/api/v1/metric-library/implementations/{SACRIFICE_IMPL}",
        {"column_id": mid, "reason": "phaseB meta-scan"},
        retries=3,
        timeout=45,
    )
    if c == "200" and b.startswith("{"):
        d = json.loads(b)
        return mid, f"{d.get('table_fqn')}.{d.get('column_name')}"
    return mid, None


def scan_map(needed: set[str], max_id: int, workers: int) -> dict[str, int]:
    mapping: dict[str, int] = {}
    # 若有旧状态则加载
    if STATE.exists():
        old = json.loads(STATE.read_text())
        mapping.update({k: int(v) for k, v in (old.get("fqn_to_id") or {}).items()})
        print(f"  loaded state map={len(mapping)}")
    remaining = needed - set(mapping)
    if not remaining:
        return {k: mapping[k] for k in needed if k in mapping}

    print(f"  scan 1..{max_id} workers={workers} need={len(remaining)}")
    done = 0
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futs = {ex.submit(probe_id, mid): mid for mid in range(1, max_id + 1)}
        for fut in as_completed(futs):
            mid, fqn = fut.result()
            done += 1
            if fqn:
                mapping[fqn] = mid
                remaining.discard(fqn)
            if done % 500 == 0 or not remaining:
                STATE.write_text(json.dumps({
                    "fqn_to_id": mapping,
                    "scanned": done,
                    "remaining": sorted(remaining)[:50],
                    "remaining_count": len(remaining),
                }, ensure_ascii=False, indent=2))
                print(f"  scanned {done}/{max_id} mapped={len(mapping)} remaining={len(remaining)}")
            if not remaining:
                # 取消剩余
                for f in futs:
                    f.cancel()
                break
    return {k: mapping[k] for k in needed if k in mapping}


def apply_patches(targets: list[dict], fqn_to_id: dict[str, int], apply: bool) -> dict:
    ok = fail = skip = 0
    errors = []
    for t in targets:
        cid = fqn_to_id.get(t["fqn"])
        if not cid:
            skip += 1
            continue
        if t.get("column_id") == cid:
            skip += 1
            continue
        body = {"column_id": cid, "reason": "phaseB backfill column_id from meta_entity"}
        if not apply:
            ok += 1
            continue
        c, b = req("PATCH", f"/api/v1/metric-library/implementations/{t['impl_id']}", body)
        if c == "200":
            ok += 1
        else:
            fail += 1
            errors.append({"impl_id": t["impl_id"], "fqn": t["fqn"], "code": c, "body": b[:200]})
            if fail <= 5:
                print(f"  FAIL impl={t['impl_id']} {t['fqn']} {c} {b[:120]}")
    return {"ok": ok, "fail": fail, "skip": skip, "errors": errors[:20]}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--max-id", type=int, default=16377)
    ap.add_argument("--workers", type=int, default=6)
    ap.add_argument("--skip-scan", action="store_true", help="只用已有 state 映射")
    args = ap.parse_args()

    print(f"base={BASE} apply={args.apply}")
    print("1) list published concepts")
    codes = list_published_codes()
    print(f"   published={len(codes)}")

    print("2) collect active impls needing column_id")
    targets = collect_targets(codes)
    needed = {t["fqn"] for t in targets}
    print(f"   targets={len(targets)} unique_fqn={len(needed)}")

    print("3) resolve meta column ids")
    if args.skip_scan and STATE.exists():
        mapping = {k: int(v) for k, v in json.loads(STATE.read_text()).get("fqn_to_id", {}).items()}
        fqn_to_id = {k: mapping[k] for k in needed if k in mapping}
    else:
        fqn_to_id = scan_map(needed, args.max_id, args.workers)
    print(f"   resolved={len(fqn_to_id)}/{len(needed)}")
    missing = sorted(needed - set(fqn_to_id))
    if missing:
        print(f"   missing sample: {missing[:15]}")

    print("4) patch implementations")
    stats = apply_patches(targets, fqn_to_id, args.apply)
    print(f"   {stats}")

    # 验收抽样
    c, b = req("GET", "/api/v1/metric-library/concepts/M000001/detail")
    if c == "200":
        d = json.loads(b)
        impl = next((i for i in d.get("implementations") or [] if i.get("id") == SACRIFICE_IMPL), None)
        print("5) sample M000001/371", {
            "column_id": (impl or {}).get("column_id"),
            "column": (impl or {}).get("column"),
            "table_fqn": (impl or {}).get("table_fqn"),
            "column_name": (impl or {}).get("column_name"),
        })

    report = {
        "published": len(codes),
        "targets": len(targets),
        "resolved": len(fqn_to_id),
        "missing": missing,
        "stats": stats,
        "apply": args.apply,
    }
    Path("/tmp/metric_v2_column_id_backfill_report.json").write_text(
        json.dumps(report, ensure_ascii=False, indent=2)
    )
    print("report -> /tmp/metric_v2_column_id_backfill_report.json")


if __name__ == "__main__":
    main()

